package com.example.pointage.ui.planning;

import java.util.Arrays;
import java.util.List;

public class PlanningSurveillance {
    private Long id_planning;
    private Long id_examen;
    private Long id_parcours;
    private String numero_salle;
    private String heure_debut;
    private String heure_fin;
    private String date_examen;
    private String surveillants; // Noms séparés par virgules
    private String created_at;

    public PlanningSurveillance() {}

    // Getters
    public Long getId_planning() { return id_planning; }
    public Long getId_examen() { return id_examen; }
    public Long getId_parcours() { return id_parcours; }
    public String getNumero_salle() { return numero_salle; }
    public String getHeure_debut() { return heure_debut; }
    public String getHeure_fin() { return heure_fin; }
    public String getDate_examen() { return date_examen; }
    public String getSurveillants() { return surveillants; }
    public String getCreated_at() { return created_at; }

    // Setters
    public void setId_planning(Long id_planning) { this.id_planning = id_planning; }
    public void setId_examen(Long id_examen) { this.id_examen = id_examen; }
    public void setId_parcours(Long id_parcours) { this.id_parcours = id_parcours; }
    public void setNumero_salle(String numero_salle) { this.numero_salle = numero_salle; }
    public void setHeure_debut(String heure_debut) { this.heure_debut = heure_debut; }
    public void setHeure_fin(String heure_fin) { this.heure_fin = heure_fin; }
    public void setDate_examen(String date_examen) { this.date_examen = date_examen; }
    public void setSurveillants(String surveillants) { this.surveillants = surveillants; }
    public void setCreated_at(String created_at) { this.created_at = created_at; }

    /**
     * Vérifie si un surveillant (par son nom) est affecté à ce planning
     */
    public boolean containsSurveillant(String nomSurveillant) {
        if (surveillants == null || surveillants.isEmpty() || nomSurveillant == null) {
            return false;
        }
        List<String> listeSurveillants = Arrays.asList(surveillants.split(","));
        for (String s : listeSurveillants) {
            if (s.trim().equalsIgnoreCase(nomSurveillant.trim())) {
                return true;
            }
        }
        return false;
    }

    /**
     * Retourne la liste des surveillants
     */
    public List<String> getListeSurveillants() {
        if (surveillants == null || surveillants.isEmpty()) {
            return Arrays.asList();
        }
        return Arrays.asList(surveillants.split(","));
    }
}

